item.command:
/bin/bash -lc "timeout 30s python - <<'PY'
import urllib.request
for name in ['README','BUILD']:
 u=f'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/9575280c875732553266e26adc607dd892b02616/doc/{name}.md'
 try:
  print(name, urllib.request.urlopen(u, timeout=10).read().decode())
 except Exception as e: print(type(e).__name__,str(e))
PY"

